import csv
import io

def sensor_data_csv(times, readings):
    if len(times) != len(readings):
        raise ValueError("times and readings must have the same length")

    output = io.StringIO()
    writer = csv.writer(output, lineterminator="\n")
    writer.writerow(["Time", "Temperature", "Humidity", "Pressure"])

    for time, (temperature, humidity, pressure) in zip(times, readings):
        writer.writerow([time, temperature, humidity, pressure])

    return output.getvalue()
