import ipaddress
import re

def list_ips_in_range(ip_range):
    if not isinstance(ip_range, str) or not re.fullmatch(
        r"(?:[0-9]+\.){3}[0-9]+/(?:0|[1-9][0-9]*)", ip_range
    ):
        raise ValueError("Invalid IPv4 CIDR range")

    try:
        network = ipaddress.IPv4Network(ip_range)
    except ValueError as exc:
        raise ValueError("Invalid IPv4 CIDR range") from exc

    return [str(address) for address in network]
```

Iterating over an `IPv4Network` includes its network and broadcast addresses. This treats an address with host bits set, such as `192.168.0.1/30`, as invalid rather than silently changing the range.

