import base64
import hashlib
import re


def salted_sha256_from_hex(hex_str: str, salt: bytes) -> tuple[str, str]:
    if re.fullmatch(r"(?:\\x[0-9a-fA-F]{2})+", hex_str):
        hex_str = hex_str.replace(r"\x", "")
    elif not re.fullmatch(r"(?:[0-9a-fA-F]{2})*", hex_str):
        raise ValueError("hex_str must contain complete hex bytes")

    data = bytes.fromhex(hex_str)
    return (
        base64.b64encode(salt).decode("ascii"),
        hashlib.sha256(salt + data).hexdigest(),
    )
```

For example, `salted_sha256_from_hex("6263", b"a")` returns `("YQ==", "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad")`.

