import base64
import hashlib
import re


def salted_sha256_from_hex(hex_str: str, salt: bytes) -> tuple[str, str]:
    if hex_str.startswith(r"\x"):
        if not re.fullmatch(r"(?:\\x[0-9a-fA-F]{2})+", hex_str):
            raise ValueError("invalid hex string")
        hex_str = hex_str.replace(r"\x", "")

    data = bytes.fromhex(hex_str)  # Raises ValueError for invalid hex.
    return (
        base64.b64encode(salt).decode("ascii"),
        hashlib.sha256(salt + data).hexdigest(),
    )
