def error_times_and_average(logs):
    times = []

    for line in logs:
        parts = line.split(maxsplit=2)
        if len(parts) != 3 or not parts[2].startswith("ERROR:"):
            continue

        hour, minute = map(int, parts[1].split(":")[:2])
