def underscore_target_phrases(target_phrases, sentences):
    phrases = [phrase.lower() for phrase in target_phrases if phrase]
    result = []

    for sentence in sentences:
        text = sentence.lower()
        replace = [False] * len(text)

        for phrase in phrases:
            start = text.find(phrase)
            while start != -1:
                for offset in range(1, len(phrase) - 1):
                    if phrase[offset] == " ":
                        replace[start + offset] = True
                start = text.find(phrase, start + 1)

        result.append("".join(
            "_" if replace[i] else char
            for i, char in enumerate(text)
        ))

    return result
```

This also handles overlapping occurrences of target phrases.

