def underscore_target_phrases(target_phrases, sentences):
    phrases = [phrase.lower() for phrase in target_phrases if " " in phrase]
    result = []

    for sentence in sentences:
        text = sentence.lower()
        replace_at = set()

        for phrase in phrases:
            start = 0
            while (start := text.find(phrase, start)) != -1:
                replace_at.update(
                    start + offset
                    for offset, char in enumerate(phrase)
                    if char == " "
                )
                start += 1  # Also find overlapping occurrences.

        result.append(
            "".join("_" if i in replace_at else char for i, char in enumerate(text))
        )

    return result
