import re

def underscore_target_phrases(target_phrases, sentences):
    patterns = [
        (phrase, re.compile(rf"(?={re.escape(phrase)})", re.IGNORECASE))
        for phrase in target_phrases
        if phrase and " " in phrase
    ]

    result = []
    for sentence in sentences:
        chars = list(sentence)
        for phrase, pattern in patterns:
            for match in pattern.finditer(sentence):
                start = match.start()
                for i in range(start, start + len(phrase)):
                    if sentence[i] == " ":
                        chars[i] = "_"
        result.append("".join(chars).lower())

    return result
```

This leaves the input lists unchanged and also handles overlapping occurrences.

