import ast


def extract_dicts(text):
    def matching_brace(start):
        depth = 0
        i = start
        quote = None

        while i < len(text):
            if quote is not None:
                if text[i] == "\\":
                    i += 2
                    continue
                if text.startswith(quote, i):
                    i += len(quote)
                    quote = None
                    continue
            else:
                if text[i] in ("'", '"'):
                    char = text[i]
                    quote = char * 3 if text.startswith(char * 3, i) else char
                    i += len(quote)
                    continue
                if text[i] == "#":
                    newline = text.find("\n", i)
                    if newline == -1:
                        return None
                    i = newline + 1
                    continue
                if text[i] == "{":
                    depth += 1
                elif text[i] == "}":
                    depth -= 1
                    if depth == 0:
                        return i + 1
            i += 1

        return None

    result = []
    i = 0
    while i < len(text):
        if text[i] != "{":
            i += 1
            continue

        end = matching_brace(i)
        if end is not None:
            try:
                value = ast.literal_eval(text[i:end])
            except (SyntaxError, ValueError, TypeError, MemoryError, RecursionError):
                pass
            else:
                if isinstance(value, dict):
                    result.append(value)
                    i = end  # Skip dictionaries nested inside this one.
                    continue
        i += 1

    return result
```

