import ast
import io
import tokenize


def extract_dicts(text):
    # Convert tokenizer (line, column) positions to string offsets.
    offsets = [0]
    for line in text.splitlines(keepends=True):
        offsets.append(offsets[-1] + len(line))

    def position_offset(position):
        line, column = position
        return offsets[line - 1] + column

    open_braces = []
    found = []

    try:
        tokens = tokenize.generate_tokens(io.StringIO(text).readline)
        for token in tokens:
            if token.type != tokenize.OP:
                continue

            if token.string == "{":
                open_braces.append(position_offset(token.start))
            elif token.string == "}" and open_braces:
                start = open_braces.pop()
                end = position_offset(token.end)
                try:
                    value = ast.literal_eval(text[start:end])
                except (SyntaxError, ValueError, TypeError, MemoryError, RecursionError):
                    continue
                if isinstance(value, dict):
                    found.append((start, end, value))
    except (tokenize.TokenError, IndentationError):
        pass

    # A valid dictionary may contain other valid dictionaries. Keep only
    # those not enclosed by another dictionary.
    found.sort(key=lambda item: item[0])
    result = []
    covered_until = -1
    for start, end, value in found:
        if start >= covered_until:
            result.append(value)
            covered_until = end
    return result
```

`ast.literal_eval` converts supported Python literals without executing code; sets and other brace-delimited expressions are not returned.

