import ast


def extract_dicts(text):
    def string_end(i):
        quote = text[i]
        delimiter = quote * 3 if text.startswith(quote * 3, i) else quote
        j = i + len(delimiter)

        while j < len(text):
            if text[j] == "\\":
                j += 2
            elif text.startswith(delimiter, j):
                return j + len(delimiter)
            elif len(delimiter) == 1 and text[j] in "\r\n":
                return None
            else:
                j += 1
        return None

    def dict_end(start):
        closing = {"{": "}", "[": "]", "(": ")"}
        stack = []
        i = start

        while i < len(text):
            char = text[i]

            if char in "\"'":
                i = string_end(i)
                if i is None:
                    return None
                continue

            if char == "#":
                newline = text.find("\n", i)
                if newline == -1:
                    return None
                i = newline + 1
                continue

            if char in closing:
                stack.append(closing[char])
            elif char in "})]":
                if not stack or stack.pop() != char:
                    return None
                if not stack:
                    return i + 1

            i += 1

        return None

    result = []
    i = 0
    while i < len(text):
        if text[i] == "{":
            end = dict_end(i)
            if end is not None:
                try:
                    value = ast.literal_eval(text[i:end])
                except (SyntaxError, ValueError, TypeError, MemoryError, RecursionError):
                    pass
                else:
                    if isinstance(value, dict):
                        result.append(value)
                        i = end  # Skip dictionaries nested inside this one.
                        continue
        i += 1

    return result
```

