import ast
import io
import tokenize


def extract_dicts(text):
    # Convert tokenize's (line, column) positions to string offsets.
    line_starts = [0] + [i + 1 for i, char in enumerate(text) if char == "\n"]

    def offset(position):
        line, column = position
        return line_starts[line - 1] + column

    openings = []
    found = []

    try:
        tokens = tokenize.generate_tokens(io.StringIO(text).readline)
        for token in tokens:
            if token.type != tokenize.OP:
                continue

            if token.string == "{":
                openings.append(offset(token.start))
            elif token.string == "}" and openings:
                start = openings.pop()
                end = offset(token.end)
                try:
                    value = ast.literal_eval(text[start:end])
                except (SyntaxError, ValueError, TypeError, RecursionError):
                    continue
                if isinstance(value, dict):
                    found.append((start, end, value))
    except (tokenize.TokenError, IndentationError):
        pass

    # A valid outer dictionary takes precedence over dictionaries inside it.
    result = []
    outer_end = -1
    for start, end, value in sorted(found, key=lambda item: (item[0], -item[1])):
        if start >= outer_end:
            result.append(value)
            outer_end = end

    return result
```

`tokenize` keeps braces inside quoted strings from being mistaken for dictionaries, and `ast.literal_eval` converts literal values without running arbitrary code.

