def most_common_letter_pair(word):
    letters = ''.join(char.lower() for char in word if char.isalpha())
    if len(letters) < 2:
        return None

    counts = {}
    best_pair = None
    best_count = 0

    for i in range(len(letters) - 1):
        pair = letters[i:i + 2]
        counts[pair] = counts.get(pair, 0) + 1
        if counts[pair] > best_count:
            best_pair, best_count = pair, counts[pair]

    return best_pair, best_count
```

