def most_common_letter_pair(word):
    letters = ''.join(char for char in word if char.isalpha()).lower()
    if len(letters) < 2:
        return None

    counts = {}
    for i in range(len(letters) - 1):
        pair = letters[i:i + 2]
        counts[pair] = counts.get(pair, 0) + 1

    # Dicts preserve first-seen order, so max() breaks ties by first appearance.
    pair = max(counts, key=counts.get)
    return pair, counts[pair]
