import ast
import json
from collections import Counter


def count_record_keys(json_text):
    counts = Counter()

    for record in json.loads(json_text):
        if isinstance(record, str):
            try:
                record = json.loads(record)
            except json.JSONDecodeError:
                try:
                    record = ast.literal_eval(record)
                except (ValueError, SyntaxError):
                    continue

        if isinstance(record, dict):
            counts.update(record.keys())

    return dict(counts)
```

This accepts dictionary strings written as either JSON or Python literals, and skips strings that do not contain a dictionary.

