import csv
from io import StringIO

def most_common_csv_value(csv_text):
    counts = {}

    for row in csv.reader(StringIO(csv_text, newline="")):
        for field in row:
            value = field.strip()
            counts[value] = counts.get(value, 0) + 1

    if not counts:
        return None

    value = max(counts, key=counts.get)
    return value, counts[value]
```

If values tie, this returns the one encountered first. Empty fields count as values.

