    counts = {}

    for row in csv.reader(io.StringIO(csv_text, newline="")):
        for field in row:
            value = field.strip()
            counts[value] = counts.get(value, 0) + 1

    # In a tie, return the value that appeared first.
    return max(counts.items(), key=lambda item: item[1]) if counts else None
```

Empty fields count as values; blank lines contain no fields.

