import csv
import io


def reverse_csv_rows(csv_text: str) -> str:
    stream = io.StringIO(csv_text, newline="")
    reader = csv.reader(stream)
    rows = []

    while True:
        start = stream.tell()
        try:
            next(reader)
        except StopIteration:
            break

        row = csv_text[start:stream.tell()]
        if row.endswith("\r\n"):
            row = row[:-2]
        elif row.endswith(("\n", "\r")):
            row = row[:-1]
        rows.append(row + "\n")

    return "".join(reversed(rows))
```

The CSV parser identifies complete rows, so line breaks inside quoted fields do not split them. Slicing the original text also preserves each row’s quoting.

```python
import csv
import io


def reverse_csv_rows(csv_text: str) -> str:
    source = io.StringIO(csv_text, newline="")
    rows = []
    start = 0

    for _ in csv.reader(source):
        end = source.tell()
        row = csv_text[start:end]

        # Remove only the record-ending newline, not line breaks inside fields.
        if row.endswith("\r\n"):
            row = row[:-2]
        elif row.endswith(("\r", "\n")):
            row = row[:-1]

        rows.append(row)
        start = end

    return "".join(row + "\n" for row in reversed(rows))
```

Using `csv.reader` to find row boundaries keeps quoted commas and line breaks within their original rows.

