import ast

def parse_dict_lines(texts):
    result = []

    for text in texts:
        for line in text.splitlines():
            try:
                expression = ast.parse(line, mode="eval").body
                if not isinstance(expression, ast.Dict):
                    raise ValueError("Not a dictionary literal")
                result.append(ast.literal_eval(expression))
            except (SyntaxError, ValueError, TypeError, RecursionError) as exc:
                raise ValueError(f"Invalid dictionary literal: {line!r}") from exc

    return result
```

A blank line is invalid; a trailing newline does not create an extra line to parse.

