import csv
from collections import Counter
from io import StringIO

def count_column_values(csv_text, column_name):
    reader = csv.reader(StringIO(csv_text))
    header = next(reader, [])

    try:
        column_index = header.index(column_name)
    except ValueError:
        raise ValueError(f"Column not found: {column_name}") from None

    counts = Counter()
    for row in reader:
        if column_index >= len(row):
            raise ValueError("A row is missing the requested column")
        counts[row[column_index]] += 1

    return dict(counts)
