def wrap_each_line(text, width):
    if width <= 0:
        raise ValueError("width must be positive")

    result = []

    for original_line in text.split("\n"):
        current = ""

        for word in original_line.split():
            if not current:
                current = word
            elif len(current) + 1 + len(word) <= width:
                current += " " + word
            else:
                result.append(current)
                current = word

        result.append(current)  # Also preserves empty input lines.

    return "\n".join(result)
```

Words longer than `width` remain whole on their own lines.

