import base64
import binascii
import json
import unicodedata


def decode_base64_json_values(json_text):
    try:
        values = json.loads(json_text)
    except json.JSONDecodeError as exc:
        raise ValueError("Invalid JSON") from exc

    if not isinstance(values, dict):
        raise ValueError("JSON must contain an object")

    result = {}
    for key, value in values.items():
        if not isinstance(value, str):
            raise ValueError(f"Value for {key!r} must be a base64 string")

        try:
            decoded = base64.b64decode(value.encode("ascii"), validate=True)
            text = decoded.decode("utf-8")
        except (binascii.Error, UnicodeError) as exc:
            raise ValueError(f"Invalid base64-encoded UTF-8 value for {key!r}") from exc

        result[key] = unicodedata.normalize("NFC", text)

    return result
```

